// EDIT THIS VALUE (one place per workflow). No other node needs changing.
const supabaseUrl = 'https://abcdefghijklmnopqrst.supabase.co';      // Supabase project URL

return [{ json: { supabaseUrl: supabaseUrl.replace(/\/+$/, '') } }];

// One item per Discord call. Each call remembers its piece of work and what it is for.
// n8n splits the list the database returns into one item per piece of work, so read them all.
const items = $input.all().map((i) => i.json);
const raw = items[0];
const work = Array.isArray(raw) ? raw : (Array.isArray(raw?.data) ? raw.data : items.filter((w) => w && w.action_id));
const out = [];
for (const w of work) {
  if (w.action === 'discord_servers') {
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'guilds', path: '/users/@me/guilds' } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'me', path: '/users/@me' } });
  }
  else if (w.action === 'discord_server') {
    if (!w.server_id) { out.push({ json: { action_id: w.action_id, action: w.action, key: 'guild', path: null } }); continue; }
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'guild', path: `/guilds/${w.server_id}` } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'channels', path: `/guilds/${w.server_id}/channels` } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'members', path: `/guilds/${w.server_id}/members/search?query=a&limit=1` } });
    // The bot's roles and the server's roles: the database works out where the bot may post.
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'roles', path: `/guilds/${w.server_id}/roles` } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'me', path: '/users/@me' } });
    if (w.bot_user_id) out.push({ json: { action_id: w.action_id, action: w.action, key: 'bot', path: `/guilds/${w.server_id}/members/${w.bot_user_id}` } });
  } else if (w.action === 'discord_member') {
    const servers = w.username ? (w.servers || []) : [];
    if (servers.length === 0) out.push({ json: { action_id: w.action_id, action: w.action, key: 'none', path: null } });
    for (const s of servers) out.push({ json: { action_id: w.action_id, action: w.action, key: 'search', server_id: s, username: w.username,
      path: `/guilds/${s}/members/search?query=${encodeURIComponent(w.username)}&limit=1000` } });
  }
}
return out;

// Put the answers of each piece of work together, in the shape record_discord_result reads.
const calls = $('Plan calls').all().map((i) => i.json);
const answers = $input.all().map((i) => i.json);
const byAction = new Map();
calls.forEach((c, n) => {
  const a = answers[n] || {};
  const status = c.path ? (a.statusCode ?? 0) : 404;
  const body = status >= 200 && status < 300 ? a.body : undefined;
  const r = byAction.get(c.action_id) || { action_id: c.action_id, result: {} };
  if (c.key === 'search') (r.result.searches ||= []).push({ server_id: c.server_id, status, body: body || [] });
  else if (c.key === 'none') r.result.searches ||= [];
  else if (c.key === 'members') r.result.members = { status };
  else r.result[c.key] = { status, body };
  byAction.set(c.action_id, r);
});
return [...byAction.values()].map((r) => ({ json: { p_action_id: r.action_id, p_result: r.result } }));
